/**
 * The selected photo in a dialog: title, close, picture, optional caption and previous/next. Static open state.
 * Used by LightboxGallery.
 */
import { type JSX } from "solid-js";
import { Button, Dialog, Group, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { MediaFrame } from "../components/media-frame";
import { tpl } from "../utils";
import type { LightboxLabels } from "../blocks/lightbox-gallery.types";
import type { Photo } from "../blocks/photo-gallery.types";

export type LightboxStageProps = {
  photos: Photo[];
  labels: LightboxLabels;
  captions?: "show" | "hide";
  lightbox?: "open" | "closed";
};

export function LightboxStage({
  photos,
  labels,
  captions = "show",
  lightbox = "closed",
}: LightboxStageProps) {
  return (
    <Dialog
      open={((lightbox as string) === "open")}
      size="xl"
      aria-label={photos[0]?.title ?? ""}
      class="gap-4 p-4"
      data-testid="lightbox"
    >
      <Group gap="2" align="center" justify="between">
        <Text size="sm" weight="semibold">
          {photos[0]?.title ?? ""}
        </Text>
        <Button
          variant="ghost"
          size="sm"
          layout="icon"
          type="button"
          aria-label={labels.close}
          data-testid="lightbox-close"
        >
          <LucideIcon name="x" size={16} />
        </Button>
      </Group>
      <MediaFrame alt={photos[0]?.title ?? ""} ratio="4/3" />
      {((captions as string) === "show") ? (
        <Text size="sm" class="text-muted-foreground">
          {photos[0]?.tag ?? ""}
        </Text>
      ) : null}
      <Group gap="2" align="center" justify="between">
        <Text size="xs" class="text-muted-foreground">
          {tpl(labels.counter, 1, (photos?.length ?? 0))}
        </Text>
        <Group gap="2">
          <Button variant="outline" size="sm" layout="icon" type="button" aria-label={labels.previous}>
            <LucideIcon name="chevron-left" size={16} />
          </Button>
          <Button variant="outline" size="sm" layout="icon" type="button" aria-label={labels.next}>
            <LucideIcon name="chevron-right" size={16} />
          </Button>
        </Group>
      </Group>
    </Dialog>
  );
}
